INSERT OR REPLACE INTO "units" VALUES(1060001500,'加贝拉·迪特','加贝拉‧迪特',3,3,2,0,'10000000006000010','600','g0600u01500','AGX-04',1,1,1,1,6672,71,734,669,732,4,39761,191,4372,3982,4159,4,61071,283,6715,6116,6378,4,3,1,3,1,2,'联邦军与阿纳海姆电子企业共同推行「高达开发计划」所试作的实验用MS再经过改装而成的机体。
由于继承了对MS战斗「最强MS」的设计理念，格斗战能力与短兵交战能力优秀，更因为装备「疾风增压推进器」，可发挥高超的机动性与加速性能。
本机体原保管于阿纳海姆电子企业，但丝玛舰队成功以独家路径接触阿纳海姆电子企业并获得转让此机体，成为「丝玛‧加拉豪」的座机。','{"id": 1060001500, "hp": 6672, "en": 71, "attack": 734, "defense": 669, "mobility": 732, "movement": 4, "max_hp": 48034, "max_en": 222, "max_attack": 5282, "max_defense": 4811, "max_mobility": 5016, "max_movement": 4, "sp_hp": 8483, "sp_en": 90, "sp_attack": 933, "sp_defense": 850, "sp_mobility": 931, "sp_movement": 4, "sp_max_hp": 61071, "sp_max_en": 283, "sp_max_attack": 6715, "sp_max_defense": 6116, "sp_max_mobility": 6378, "sp_max_movement": 4}','{"unit_id": 1060001500, "unit_ssp_initial_release_set_id": 1060001500, "unit_ssp_custom_core_group_id": 1060001500, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 106000150001, "unit_ssp_custom_core_group_id": 1060001500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000150001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000150001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000150001, "weapon_change": {"id": 106000150001, "before_weapon_id": 0, "after_weapon_id": 106000150090, "weapon": {"id": 106000150090, "name": "鐳射機槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000150090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000150090, "weapon_status": {"id": 106000150090, "range_min": 2, "range_ma